\u006b\u004e\u0060\u004b\u003b\u0041\u0045\u003c\u007c\u007d\u0035\u0047\u0031\u003c\u004e\u003b\u0048\u0030\u004e\u0029\u002e\u002a\u0043\u004b\u0041\u0041\u005d\u0069\u0041\u0076\u0052\u0047\u0048\u0059\u0042\u0045\u0062\u0051\u0064\u005d\u006d\u0034\u0065\u0062\u0055\u007d\u0039\u0036\u0040\u004f\u002f\u002b\u002e\u003c\u007c\u0056\u003b\u0049\u006e\u007a\u0062\u003b\u0055\u0056\u0033\u003a\u007c\u006b\u007d\u005b\u0026\u005d\u004b\u003b\u0075\u002e\u0058\u0033\u0053\u007e\u0025\u0048\u0044\u0052\u0045\u002c\u0037\u007c\u0033\u0071\u0051\u0055\u007e\u0074\u003d\u0076\u007b\u0045\u0072\u0041\u0037\u0049\u0059\u0046\u007a\u0040\u003a\u003f\u0032\u002a\u0064\u0060\u003d\u0025\u0061\u004d\u0025\u0037\u0040\u0046\u0047\u0048\u0072\u002e\u0070\u0050\u0072\u002c\u006a\u0060\u0044\u0079\u004c\u003a\u007c\u006b\u007d\u005b\u0026\u005d\u006d\u004a\u004c\u006f\u0064\u003e\u006e\u0040\u002a\u0022\u0068\u0042\u005a\u0042\u0029\u003c\u0078\u005d\u0053\u0054\u005f\u004a\u0065\u0047\u0031\u003c\u007c\u0056\u007b\u0021\u007b\u0046\u0025\u0044\u0040\u004e\u0065\u0071\u0029\u002c\u007e\u0063\u0033\u0044\u003e\u0025\u0048\u005d\u0059\u0062\u0023\u004e\u0029\u0028\u003c\u0044\u0024\u005d\u0025\u0042\u007e\u0078\u002e\u0030\u0043\u003c\u0049\u0052\u0036\u006a\u003d\u004a\u0057\u0063\u0060\u0066\u0072\u0042\u007c\u0045\u0069\u0079\u007e\u0038\u003d\u004b\u002a\u004c\u0037\u004e\u0071\u0050\u0039\u0040\u0061\u006f\u0048\u007b\u0055\u0066\u0064\u0061\u005f\u0031\u005f\u006f\u005e\u0025\u0054\u005a\u0074\u0033\u0056\u007a\u004b\u0076\u0043\u0052\u0034\u0074\u006e\u007a\u005a\u0064\u0028\u004d\u0040\u003b\u003c\u0030\u004a\u0033\u0047\u0037\u0034\u0031\u0070\u0026\u007a\u0072\u0062\u0025\u0038\u0057\u0071\u0058\u005b\u0026\u004c\u0060\u0023\u0052\u006e\u0023\u004f\u007d\u0042\u0038\u0072\u0030\u0023\u006c\u0046\u004d\u007a\u0047\u0031\u0031\u0040\u004a\u006f\u0058\u004f\u004f\u0043\u0029\u0072\u002e\u003f\u0057\u004c\u0028\u0076\u0033\u0029\u005e\u0068\u002f\u0050\u0058\u0055\u0023\u0036\u0037\u0038\u0058\u0040\u0040\u005a\u0023\u0038\u0072\u0023\u004e\u0036\u005a\u0055\u0022\u0021\u0055\u003d\u005e\u0022\u007c\u0041\u0039\u0070\u005d\u007e\u0077\u0075\u0028\u007b\u0047\u0064\u0064\u0055\u0066\u003c\u0031\u0036\u0076\u0025\u0056\u005f\u002a\u0046\u0058\u002e\u003b\u004b\u002a\u0067\u0033\u0073\u0046\u007a\u002c\u0079\u003b\u0046\u0036\u0031\u0030\u0056\u005f\u0038\u0050\u003b\u005e\u0024\u005e\u0031\u0072\u0060\u0044\u0051\u0022\u0074\u003f\u0033\u002e\u005d\u0025\u0077\u0061\u007d\u003f\u0073\u0038\u0041\u0035\u0071\u004e\u0035\u0062\u0058\u0025\u0031\u0044\u004d\u006b\u0063\u006b\u0078\u0076\u0052\u0077\u007c\u007e\u0050\u002a\u0043\u0038\u007d\u0050\u0040\u0043\u0060\u007c\u0035\u0079\u0073\u003e\u0075\u0064\u004c\u0028\u004f\u004d\u006c\u0029\u0038\u003e\u0041\u0057\u0064\u0046\u005e\u005b\u0058\u0060\u007c\u0029\u0038\u0057\u0042\u004a\u0061\u007d\u003f\u0073\u0038\u0041\u0035\u0071\u003c\u0077\u006b\u0029\u0043\u0045\u0075\u0052\u0043\u0056\u0065\u0065\u003d\u005d\u0026\u0026\u006f\u0057\u0035\u0079\u0024\u004c\u002a\u0064\u0040\u006b\u004c\u005a\u005b\u0075\u0024\u004a\u007c\u0039\u007b\u0024\u004c\u002a\u0064\u004e\u0064\u0069\u002f\u0062\u0048\u0039\u0041\u0041\u0029\u0064\u004c\u0036\u0029\u007b\u0067\u0055\u002e\u0039\u004d\u006e\u0039\u0054\u0074\u0044\u0077\u007c\u003f\u004a\u002b\u0055\u003c\u007d\u0069\u007b\u0030\u0060\u0047\u006e\u0036\u0032\u007a\u004f\u003c\u0062\u003b\u0060\u0042\u0041\u004e\u0070\u0075\u0026\u006b\u0043\u0071\u0042\u0050\u0050\u006c\u0075\u004e\u0033\u0031\u0049\u007b\u004f\u004e\u0038\u002c\u0058\u0030\u0046\u0023\u0055\u007e\u004e\u0078\u0069\u0030\u0046\u007c\u006f\u0038\u002f\u0067\u006c\u003c\u0071\u0071\u0032\u003e\u007b\u0071\u0070\u004f\u0049\u006f\u002e\u005b\u0061\u0058\u0053\u002f\u0046\u0023\u0066\u0043\u007d\u0064\u0030\u002a\u006c\u006d\u004e\u0028\u002b\u0051\u003b\u002b\u0062\u004f\u0063\u005e\u0029\u0079\u0050\u0053\u006c\u003d\u003e\u0034\u006a\u003c\u0044\u003e\u004e\u0058\u0075\u007e\u0047\u006f\u005d\u007b\u0069\u0021\u0055\u0042\u003a\u0047\u0077\u0078\u0052\u0035\u006f\u0049\u007b\u0021\u0061\u006f\u0076\u0031\u0031\u0051\u0048\u003b\u0077\u0036\u0058\u0042\u005f\u0036\u0028\u006c\u0058\u002c\u0051\u0038\u004e\u0051\u0036\u004e\u0077\u0036\u004c\u0069\u006d\u003a\u0028\u0067\u0046\u0056\u0034\u0070\u0066\u0051\u0076\u0023\u0045\u0045\u0045\u0031\u006f\u0070\u005f\u0057\u006e\u002a\u0055\u003e\u0056\u0045\u0045\u0039\u0033\u0072\u006a\u0061\u0049\u0029\u004a\u007d\u002c\u0076\u0032\u002e\u002b\u003a\u007b\u003e\u0060\u0023\u007c\u0041\u003a\u0068\u0035\u003f\u004d\u0025\u0029\u0042\u0035\u0049\u004f\u006f\u0052\u0040\u0054\u0051\u002e\u0074\u007e\u004e\u0048\u0069\u0054\u007b\u003b\u0049\u0026\u003f\u005e\u0069\u0071\u0032\u0033\u0077\u0061\u0065\u0061\u0049\u002f\u0064\u0021\u004e\u0057\u0069\u0064\u006b\u0068\u005d\u0061\u006d\u004e\u006c\u0075\u0058\u0042\u0052\u005f\u0039\u0062\u0048\u007a\u002b\u003f\u0056\u0075\u007a\u003a\u003e\u0045\u0061\u002e\u002f\u003f\u007d\u003d\u0028\u006f\u0032\u0032\u0034\u0059\u0041\u004e\u0078\u0057\u006a\u004e\u006d\u0062\u0078\u0045\u0036\u0054\u006b\u007d\u004d\u002a\u0065\u007a\u0028\u0031\u005b\u007e\u0022\u0059\u0065\u0060\u0064\u007b\u0052\u003f\u0024\u0052\u0028\u004a\u006c\u0044\u003c\u0032\u0055\u0055\u0051\u002e\u0045\u0067\u0067\u0034\u005b\u0048\u004b\u0071\u006b\u0055\u0069\u0022\u0033\u003c\u007c\u0026\u0075\u0049\u0053\u002c\u0056\u0034\u002e\u003e\u005a\u0047\u0034\u0049\u0041\u0032\u0074\u0023\u002c\u004c\u0062\u002e\u004a\u004f\u0042\u0077\u002a\u002c\u0076\u0073\u0024\u005d\u0068\u0037\u006c\u0023\u0026\u0022\u007a\u0072\u0041\u003b\u0032\u006d\u0055\u005d\u0062\u0031\u003c\u0078\u0042\u0071\u0062\u0070\u004f\u003c\u0030\u003e\u0072\u0036\u0060\u0054\u0065\u0033\u0072\u0034\u006e\u0054\u006a\u0030\u007c\u0065\u0053\u0023\u002f\u0053\u0035\u0073\u0028\u005a\u0060\u0054\u005a\u003f\u0021\u004e\u0057\u0069\u0064\u006b\u002e\u007e\u0066\u002f\u0039\u004d\u005d\u0026\u0075\u0057\u004d\u0033\u0035\u002b\u0070\u003d\u0042\u0078\u0064\u0025\u0047\u006c\u0045\u0072\u006a\u0064\u004f\u0063\u0028\u004d\u005f\u004e\u0032\u0058\u005a\u0033\u0070\u0049\u007c\u004a\u0073\u0021\u0044\u005f\u0037\u003a\u0029\u0076\u0054\u0054\u0071\u002b\u0024\u0025\u0022\u0060\u0056\u005a\u006d\u005f\u0028\u007b\u002e\u0067\u0022\u0060\u0046\u0073\u0066\u0031\u0038\u005b\u0034\u0048\u0076\u003b\u0043\u0044\u004e\u0042\u0072\u003a\u0041\u0026\u004a\u007c\u002e\u005b\u0026\u0065\u0049\u007a\u0034\u0063\u0035\u002b\u0021\u005a\u0046\u0031\u0066\u004d\u0071\u002b\u0038\u007a\u007e\u0031\u006d\u004a\u003c\u0058\u0042\u0029\u004d\u005d\u0047\u0047\u0025\u0041\u003f\u0057\u005e\u0077\u0029\u0056\u004f\u0049\u0033\u003d\u0077\u0069\u0056\u005e\u0051\u003b\u0053\u006b\u003b\u0055\u0036\u0068\u003b\u0071\u003c\u004f\u003f\u0057\u005e\u0077\u0029\u0056\u0033\u007a\u0067\u002e\u004f\u0063\u005d\u0036\u004f\u0038\u005b\u007e\u004f\u0060\u002f\u0049\u004f\u004b\u0079\u0040\u0068\u0032\u005d\u0023\u0044\u0062\u005e\u0057\u003b\u0026\u0059\u003a\u0045\u006c\u0039\u0034\u0041\u0046\u0077\u0052\u0041\u0023\u0074\u003d\u007d\u0038\u0032\u0030\u0034\u0024\u006a\u004d\u002b\u0065\u0039\u007b\u002f\u0068\u0036\u0070\u0078\u0034\u007c\u0053\u0055\u0057\u0036\u0068\u0062\u007d\u005e\u0059\u0032\u0070\u0053\u0061\u0076\u005a\u0057\u0036\u0068\u0062\u004f\u0057\u0063\u0029\u006d\u0032\u0031\u0034\u007d\u005b\u0068\u0032\u005d\u0023\u0044\u0062\u0059\u0039\u0022\u0061\u0025\u0029\u0038\u0025\u0030\u0046\u0035\u0061\u002f\u0072\u002f\u007d\u0056\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0032\u0034\u0056\u006a\u007c\u004e\u006d\u0057\u0044\u0058\u0037\u002e\u003e\u006b\u002c\u0024\u007a\u007d\u0051\u007b\u0037\u0071\u0048\u0072\u0067\u0046\u0041\u006e\u005b\u006b\u005a\u0029\u0079\u006b\u003b\u0067\u0066\u0025\u0059\u007b\u004e\u007b\u0039\u0033\u0049\u0060\u005a\u0029\u0037\u006b\u005f\u0055\u0032\u0060\u0045\u002c\u0063\u005d\u004b\u0060\u0043\u003b\u0069\u006d\u0028\u0076\u0039\u004a\u005a\u004e\u003a\u004d\u002f\u007c\u007a\u005e\u0041\u003c\u0055\u004a\u0067\u0032\u003b\u005f\u0061\u0029\u006d\u004a\u006f\u0067\u003f\u005f\u0068\u0021\u006a\u0054\u0076\u0065\u0038\u0056\u0061\u0029\u0057\u0048\u0040\u0067\u003c\u0068\u0034\u004e\u0075\u007a\u005d\u003a\u005f\u0030\u0046\u0066\u0039\u003d\u005d\u004e\u0029\u0076\u005e\u0023\u0052\u0068\u0047\u0032\u0063\u0049\u0035\u0029\u0072\u006b\u003b\u0067\u003e\u0025\u0059\u007b\u0075\u007b\u0041\u006c\u0057\u0057\u0065\u0041\u0070\u004d\u0028\u005d\u0037\u0079\u0042\u0058\u0064\u0054\u006c\u005b\u005f\u0030\u0046\u0066\u0039\u003d\u005d\u004e\u0029\u0076\u005e\u0023\u0052\u0068\u0047\u0032\u0063\u0049\u0035\u0029\u0072\u006b\u003b\u0067\u003e\u0025\u0059\u007b\u0075\u007b\u0041\u006c\u0057\u0057\u0039\u0053\u003b\u0024\u0042\u0078\u007c\u007b\u0042\u0022\u003b\u0067\u007a\u002a\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0032\u0034\u006a\u0078\u0039\u0032\u0044\u0078\u002a\u0034\u0035\u0026\u005d\u0063\u0074\u0033\u002a\u0079\u0023\u0041\u0022\u0071\u0040\u0030\u0068\u0045\u0074\u0058\u0055\u0025\u006c\u0073\u0063\u0042\u0030\u0031\u004a\u0059\u007b\u004e\u007b\u0038\u0033\u0050\u007b\u0078\u0061\u0021\u003a\u007c\u0075\u0024\u003b\u0067\u0040\u0034\u0069\u0069\u0076\u0063\u0052\u007d\u003f\u0070\u0078\u0069\u0049\u0076\u0040\u005b\u003a\u0074\u0052\u0036\u005a\u003c\u0079\u0038\u0045\u0059\u0069\u0040\u005f\u003b\u0067\u0040\u0034\u0058\u0023\u004b\u005e\u0034\u006a\u0042\u005b\u002c\u002a\u0068\u006a\u0074\u006d\u0062\u003a\u005e\u0060\u0034\u0039\u0030\u006c\u0057\u0049\u007e\u0067\u0076\u004b\u005f\u0056\u0055\u0069\u0050\u0021\u0038\u0072\u0032\u0035\u004c\u0025\u006b\u004a\u0033\u0036\u0075\u0046\u0037\u005f\u0049\u006c\u0028\u0050\u002c\u007e\u0058\u005d\u0043\u0042\u0046\u0037\u005f\u0049\u003f\u0057\u0068\u003b\u0067\u0026\u0067\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0070\u004d\u002a\u0058\u0037\u0079\u0032\u0055\u003b\u0067\u0066\u0025\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0070\u004d\u002a\u0058\u0037\u0079\u0032\u0055\u003b\u0067\u0066\u0025\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0070\u004d\u002a\u0058\u0037\u0079\u0032\u0055\u003b\u0067\u0066\u0025\u0059\u007b\u004e\u007b\u0038\u0033\u0057\u0057\u0062\u0026\u0070\u004d\u002a\u0058\u0053\u006b\u0049\u0054\u005a\u0077\u005e\u003f\u0039\u0047\u0039\u0068\u0059\u0030\u0079\u005d\u0055\u0067\u0039\u004a\u0033\u0036\u0075\u004f\u002f\u0066\u0073\u003e\u0030\u0066\u006c\u0021\u0021\u0070\u0041\u0030\u0048\u0031\u003d\u003f\u0039\u0047\u0039\u0068\u0059\u0028\u0049\u002b\u0068\u0054\u0077\u0040\u0021\u0045\u002a\u0050\u0078\u004c\u0060\u007a\u0035\u0069\u0074\u0022\u0022\u002a\u007e\u005b\u0059\u005f\u004b\u002a\u006b\u0066\u0055\u005e\u003c\u003a\u007a\u006b\u0040\u0030\u0071\u0045\u004c\u0046\u003f\u0042\u005b\u006b\u0078\u007e\u005e\u006f\u0052\u0026\u0048\u006a\u0047\u0049\u0026\u002f\u0056\u0032\u0030\u0060\u0076\u0039\u006b\u003b\u0048\u0049\u0044\u0030\u0028\u0042\u007b\u0030\u007e\u0078\u006a\u004e\u0074\u0022\u0076\u0076\u005a\u005b\u0063\u0021\u0033\u006d\u007b\u0064\u0051\u0058\u0066\u0038\u002a\u003b\u0076\u0039\u0045\u0050\u002b\u0034\u0034\u0041\u006c\u0044\u0049\u002f\u0052\u007a\u0072\u002b\u006f\u0074\u0044\u005b\u003d\u005a\u003c\u0079\u0035\u0050\u006e\u0054\u005e\u0077\u003a\u0060\u0077\u0050\u003f\u0079\u0041\u007c\u0024\u0021\u0060\u0036\u0075\u0032\u0029\u0075\u0079\u0066\u006d\u0076\u0045\u0077\u005d\u003e\u0071\u005a\u005f\u006f\u0074\u0050\u003a\u0060\u0043\u0042\u0030\u0048\u0039\u0078\u0023\u003a\u0030\u0056\u0065\u0075\u0039\u006c\u0046\u0049\u0033\u0054\u0037\u0056\u0046\u005f\u0039\u0075\u0036\u007b\u0061\u0049\u004e\u005e\u006b\u0059\u0069\u003b\u0054\u0051\u007b\u0043\u006e\u0023\u006f\u0046\u002c\u0039\u003e\u0064\u0069\u0074\u0024\u0031\u003a\u0075\u004e\u006a\u004a\u0056\u005b\u0032\u0056\u0038\u004f\u005a\u0052\u0069\u0066\u0031\u0042\u0060\u007d\u003a\u003f\u003f\u002e\u0070\u0041\u0040\u006a\u0021\u0025